import { Order } from './types';

// A position in the listing order. Cursors point at positions, not at rows,
// so a position stays valid even if the row it was taken from is deleted.
export interface OrderPosition { createdAt: string; id: string }

// Ascending by createdAt, then id; both compared as strings (lexicographic).
function compareOrders(a: OrderPosition, b: OrderPosition): number {
  if (a.createdAt !== b.createdAt) return a.createdAt < b.createdAt ? -1 : 1;
  if (a.id !== b.id) return a.id < b.id ? -1 : 1;
  return 0;
}

export class OrderRepository {
  constructor(private readonly rows: Order[]) {}

  list(tenant: string): Order[] {
    // filter() returns a new array, so sorting it never touches this.rows.
    return this.rows.filter(row => row.tenant === tenant).sort(compareOrders);
  }

  // The tenant's orders strictly after `after` in (createdAt, id) order.
  // The tenant filter is applied before the position comparison.
  listAfter(tenant: string, after: OrderPosition): Order[] {
    return this.list(tenant).filter(row => compareOrders(row, after) > 0);
  }
}
